_choice_ansible_become_method() {
    command -v ansible-doc >/dev/null || return 0
    ansible-doc -t become -l 2>/dev/null |
        gawk 'NF >= 2 { name = $1; $1 = ""; sub(/^ +/, ""); sub(/ +$/, ""); print name "\t" $0 }'
}

_choice_ansible_connection() {
    command -v ansible-doc >/dev/null || return 0
    ansible-doc -t connection -l 2>/dev/null |
        gawk 'NF >= 2 { name = $1; $1 = ""; sub(/^ +/, ""); sub(/ +$/, ""); print name "\t" $0 }'
}

_choice_ansible_host() {
    command -v ansible-inventory >/dev/null || return 0
    local inv=() item
    for item in "${argc_inventory[@]:-}" "${argc_inventory_file[@]:-}"; do
        [[ -n "$item" ]] && inv+=(-i "$item")
    done
    ansible-inventory "${inv[@]}" --list 2>/dev/null |
        jq -b -r '(.. | objects | (.children? // empty)[]), (.. | objects | (.hosts? // empty)[])' 2>/dev/null
}

_choice_ansible_module() {
    command -v ansible-doc >/dev/null || return 0
    local out
    out=$(ansible-doc -t module -l 2>/dev/null) || true
    if [[ -z "$out" ]]; then
        out=$(ansible-doc -t module -l ansible.builtin 2>/dev/null) || true
    fi
    printf '%s\n' "$out" |
        gawk 'NF >= 2 { name = $1; $1 = ""; sub(/^ +/, ""); sub(/ +$/, ""); print name "\t" $0 }'
}
